#!/usr/bin/env bash
# Writes to stdout the golden.json the llmsearch tokenizer, porter and
# keyword tests compare against, built by the system sqlite3 (with FTS5)
# from:
#
#   corpus.txt   one row per line: name, a tab, then body ("\n" is a newline)
#   queries.txt  one FTS5 MATCH expression per line, as DigUp writes them
#   porter.txt   one word per line
#
# The table mirrors DigUp's fts table (IndexStore.swift): columns name and
# body indexed, original UNINDEXED, and the same tokenizer. Ties in bm25 are
# ordered by rowid. Regenerate with `make -C internal/llm/llmsearch/testdata/fts5`.
set -euo pipefail
cd "$(dirname "$0")"

categories="categories 'L* N* Co M*'"
tokenize="porter unicode61 remove_diacritics 2 $categories"
raw="unicode61 remove_diacritics 2 $categories"

lit() {
	awk -F'\t' -v q="'" -v table="$1" '
		function lit(s) { gsub(q, q q, s); gsub(/\\n/, "\n", s); return q s q }
		table == "fts" && NF { printf "INSERT INTO fts(name, body) VALUES(%s, %s);\n", lit($1), lit($2) }
		table != "fts" && NF { printf "INSERT INTO %s VALUES(%s);\n", table, lit($0) }'
}

{
	cat <<EOF
CREATE VIRTUAL TABLE fts USING fts5(name, body, original UNINDEXED, tokenize = "$tokenize");
CREATE VIRTUAL TABLE raw USING fts5(name, body, tokenize = "$raw");
CREATE VIRTUAL TABLE words USING fts5(word, tokenize = "$tokenize");
CREATE VIRTUAL TABLE fts_i USING fts5vocab(fts, instance);
CREATE VIRTUAL TABLE raw_i USING fts5vocab(raw, instance);
CREATE VIRTUAL TABLE words_i USING fts5vocab(words, instance);
CREATE TABLE queries(q TEXT NOT NULL);
EOF
	lit fts <corpus.txt
	lit words <porter.txt
	lit queries <queries.txt
	cat <<'EOF'
INSERT INTO raw(rowid, name, body) SELECT rowid, name, body FROM fts;
SELECT json_pretty(json_object(
	'comment', 'Generated by gen.sh with the system sqlite3; do not edit.',
	'sqlite', sqlite_version(),
	'rows', (SELECT json_group_array(json_object(
		'rowid', f.rowid, 'name', f.name, 'body', f.body,
		'raw', json_object(
			'name', (SELECT json_group_array(term ORDER BY offset) FROM raw_i WHERE doc = f.rowid AND col = 'name'),
			'body', (SELECT json_group_array(term ORDER BY offset) FROM raw_i WHERE doc = f.rowid AND col = 'body')),
		'stemmed', json_object(
			'name', (SELECT json_group_array(term ORDER BY offset) FROM fts_i WHERE doc = f.rowid AND col = 'name'),
			'body', (SELECT json_group_array(term ORDER BY offset) FROM fts_i WHERE doc = f.rowid AND col = 'body'))
		) ORDER BY f.rowid) FROM fts f),
	'porter', (SELECT json_group_array(json_object(
		'word', w.word,
		'stems', (SELECT json_group_array(term ORDER BY offset) FROM words_i WHERE doc = w.rowid)
		) ORDER BY w.rowid) FROM words w),
	'queries', (SELECT json_group_array(json_object(
		'match', qq.q,
		'hits', (SELECT json_group_array(json(h)) FROM (
			SELECT json_object(
				'rowid', rowid,
				'bm25', bm25(fts, 3.0, 1.0),
				'snippet', snippet(fts, 1, '«', '»', '…', 12)) AS h
			FROM fts WHERE fts MATCH qq.q ORDER BY bm25(fts, 3.0, 1.0), rowid))
		) ORDER BY qq.rowid) FROM queries qq)
));
EOF
} | sqlite3 :memory: